/** The error a call rejects with: the C# method threw, or its arguments did not fit its parameters. */
export class CallError extends Error {
  /** The method that failed, as "Service.Method". */
  readonly method: string;

  constructor(method: string, message: string) {
    super(message);
    this.name = "CallError";
    this.method = method;
  }
}

interface Bridge {
  call(method: string, args: unknown[]): Promise<unknown>;
  on(event: string, listener: (payload: unknown) => void): () => void;
}

function bridge(): Bridge {
  const runtime = (globalThis as { oriel?: Bridge }).oriel;
  if (!runtime) throw new Error("Oriel: window.oriel is missing; open this page in an Oriel window");
  return runtime;
}

async function call<T>(method: string, ...args: unknown[]): Promise<T> {
  // Arguments left out stay out, so that C# uses its defaults.
  while (args.length > 0 && args[args.length - 1] === undefined) args.pop();
  try {
    return (await bridge().call(method, args)) as T;
  } catch (err) {
    if (err instanceof Error && err.name === "CallError") throw new CallError(method, err.message);
    throw err;
  }
}

function on<T>(event: string, listener: (payload: T) => void): () => void {
  return bridge().on(event, listener as (payload: unknown) => void);
}

// ---- Types ----

/** A greeting, and when it was made. */
export interface Greeting {
  text: string;
  tone: Tone;
  at: string;
}

/** What runs the app. */
export interface MachineInfo {
  system: string;
  runtime: string;
  processors: number;
  nativeAot: boolean;
}

/** How a greeting sounds. */
export type Tone = "friendly" | "formal" | "pirate";

// ---- Services ----

/** Tells pages the time. */
export const Clock = {
  /**
   * Fires every second with the time.
   * Calls listener with each payload of Clock.Tick; returns a function that stops listening.
   */
  onTick(listener: (payload: string) => void): () => void {
    return on<string>("Clock.Tick", listener);
  },
} as const;

/** Greets people. */
export const Greeter = {
  /**
   * Greets name.
   * @param name Who to greet.
   * @param tone How the greeting sounds.
   */
  greet(name: string, tone?: Tone): Promise<Greeting> {
    return call("Greeter.Greet", name, tone);
  },
} as const;

/** Describes the machine. */
export const Machine = {
  /** The system and runtime the app runs on. */
  describe(): Promise<MachineInfo> {
    return call("Machine.Describe");
  },
} as const;
